---8<---
import { ListView, type ListItem } from "@gtkx/components";
import * as Gtk from "@gtkx/gi/gtk";
import { GtkLabel, GtkScrolledWindow } from "@gtkx/jsx/gtk";
import { render, screen, within } from "@gtkx/testing";
import { describe, expect, it } from "vitest";

type Row = { name: string };

const renderItem = ({ item }: { item: Row }) => <GtkLabel>{item.name}</GtkLabel>;

const rowTexts = (): string[] =>
    screen.queryAllByRole(Gtk.AccessibleRole.LIST_ITEM).map((w) =>
        within(w).queryAllByRole(Gtk.AccessibleRole.LABEL, { as: Gtk.Label }).map((l) => l.label).join(""),
    );

const chainOf = (depth: number): ListItem<Row>[] => {
    let node: ListItem<Row> = { id: `n${depth - 1}`, value: { name: `n${depth - 1}` } };
    for (let i = depth - 2; i >= 0; i -= 1) {
        node = { id: `n${i}`, value: { name: `n${i}` }, children: [node] };
    }
    return [node];
};

const renderChain = async (depth: number): Promise<string> => {
    try {
        await render(
            <GtkScrolledWindow widthRequest={300} heightRequest={400} vexpand hexpand>
                <ListView<Row> items={chainOf(depth)} renderItem={renderItem} />
            </GtkScrolledWindow>,
        );
        return "ok";
    } catch (error) {
        return error instanceof Error ? `${error.constructor.name}: ${error.message}` : "unknown";
    }
};

describe("collapsed deep and cyclic trees", () => {
    it("a finite chain crashes past about two thousand levels", async () => {
        const results: Record<string, string> = {};
        for (const depth of [500, 1000, 3000, 8000]) {
            results[String(depth)] = await renderChain(depth);
        }
        expect(results).toEqual({ "500": "ok", "1000": "ok", "3000": "ok", "8000": "ok" });
    });

    it("a node that is its own child crashes with nothing expanded", async () => {
        const node: ListItem<Row> = { id: "loop", value: { name: "loop" } };
        node.children = [node];
        await render(
            <GtkScrolledWindow widthRequest={300} heightRequest={400} vexpand hexpand>
                <ListView<Row> items={[node]} renderItem={renderItem} />
            </GtkScrolledWindow>,
        );
        expect(rowTexts()).toEqual(["loop"]);
    });

    it("two nodes that reference each other crash the same way", async () => {
        const a: ListItem<Row> = { id: "a", value: { name: "a" } };
        const b: ListItem<Row> = { id: "b", value: { name: "b" }, children: [a] };
        a.children = [b];
        await render(
            <GtkScrolledWindow widthRequest={300} heightRequest={400} vexpand hexpand>
                <ListView<Row> items={[a]} renderItem={renderItem} />
            </GtkScrolledWindow>,
        );
        expect(rowTexts()).toEqual(["a"]);
    });
});
