import { ListView, type ListItem } from "@gtkx/components";
import { GtkApplication, GtkApplicationWindow, GtkLabel, GtkScrolledWindow } from "@gtkx/jsx/gtk";
import { createRoot, quit } from "@gtkx/react";

type Row = { name: string };

const DEPTH = Number(process.env.DEEP_DEPTH ?? "3000");

const chainOf = (depth: number): ListItem<Row>[] => {
    let node: ListItem<Row> = { id: `n${depth - 1}`, value: { name: `n${depth - 1}` } };
    for (let i = depth - 2; i >= 0; i -= 1) {
        node = { id: `n${i}`, value: { name: `n${i}` }, children: [node] };
    }
    return [node];
};

const items = chainOf(DEPTH);
const renderItem = ({ item }: { item: Row }) => <GtkLabel>{item.name}</GtkLabel>;

const App = () => (
    <GtkApplication applicationId="com.gtkx.collectionsr3deep">
        <GtkApplicationWindow title="Deep" defaultWidth={400} defaultHeight={400} onCloseRequest={quit}>
            <GtkScrolledWindow widthRequest={400} heightRequest={400} vexpand hexpand>
                <ListView<Row> items={items} renderItem={renderItem} />
            </GtkScrolledWindow>
        </GtkApplicationWindow>
    </GtkApplication>
);

createRoot().render(<App />);

setTimeout(() => { console.log("still alive after 3s"); quit(); }, 3000);
